export type Market = "NG" | "CA" | "WORLD";
export type BillingMode = "monthly" | "one_time";

export interface RestaurantConfig {
  slug: string;
  legalName: string;
  displayName: string;
  market: Market;
  city: string;
  country: string;
  domain: { primary: string; registrar: string; email: string };
  contacts: { phone: string; whatsapp: string; instagram: string };
  hours: { day: string; open: string; close: string }[];
  skin: {
    anchorRef: string;
    spine: string;
    direction: string;
    palette: { bg: string; surface: string; ink: string; accent: string; accent2: string };
    type: { display: string; serif: string; body: string; mono: string };
    layoutVariant: "flip-first" | "list-first";
  };
  signatureDish: { itemRef: string };
  firstBite: { framesBaseUrl: string; posterUrl: string; durationSec: number };
  cloudinary: { cloudName: string; folder: string };
  billing: { mode: BillingMode; planCode: string | null; paymentPageUrl: string | null };
  editor: { ownerEmail: string };
  registryState: "prospect" | "awaiting_payment" | "building" | "live" | "grace" | "paused" | "lifetime" | "churned";
  currency: string;
  timezone: string;
}

